{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "api" });
  const candidates = issues.filter((i) => i.status === "unresolved" && i.count >= 0);

  const created: string[] = [];
  let firstTitle: string | null = null;
  const skipped: string[] = [];

  for (const issue of candidates) {
    // is this culprit already mentioned by a Linear issue?
    const { issues: found } = await sdk.linear.searchIssues({ query: issue.culprit });
    const mentioned = found.some(
      (l) => l.description.includes(issue.culprit) || l.title.includes(issue.culprit)
    );
    if (mentioned) {
      skipped.push(`${issue.shortId} (${issue.culprit}) already in ${found[0]?.identifier}`);
      continue;
    }
    if (firstTitle === null) firstTitle = issue.title;
    const blame = await sdk.github.getBlame({ file: issue.filename, line: issue.lineNumber });
    const res = await sdk.linear.createIssue({
      title: `[Sentry] ${firstTitle}`,
      description: issue.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push(res as unknown as string);
  }

  return { checked: candidates.length, created, skipped, firstTitle };
}"}
